def isvalid(version):
    try:
        VersionInfo(*parse(version))
        return True
    except ValueError:
        return False

def check(version):
    print(isvalid(version))

    if not isvalid(version):
        sys.exit(1)

def main(args):
    parser = createparser()
    args = parser.parse_args(args)
    if args.check:
        check(args.version)
    else:
        pysemver.finalize_version(args.version)

def createparser():
    parser = argparse.ArgumentParser(description='Semantic versioning CLI')
    parser.add_argument('--compare', nargs=2, help='Compare two versions')
    parser.add_argument('--check', action='store_true', help='Check version validity')
    parser.add_argument('--version', help='Version to check/comparison')
    subparsers = parser.add_subparsers(dest='subparsers', help='Available subcommands')
    cmd_bump = subparsers.add_parser('bump', help='Bump version')
    cmd_bump.add_argument('--minor', action='store_true', help='Bump minor version')
    cmd_bump.add_argument('--patch', action='store_true', help='Bump patch version')
    cmd_check = subparsers.add_parser('check', help='Check version validity')
    cmd_compare = subparsers.add_parser('compare', help='Compare two versions')
    return parser

def finalize_version(version):
    print(parse_version_info(version))

def process(args):
    print(parse_version_info(args.version))

def cmd_bump(args):
    print('Bumping version...')

def cmd_compare(args):
    ver1, ver2 = args.version
    print(compare(ver1, ver2))

def cmd_check(args):
    check(args.version)

def main(args):
    parser = createparser()
    args = parser.parse_args(args)
    if args.subparsers == 'bump':
        cmd_bump(args)
    elif args.subparsers == 'check':
        cmd_check(args)
    elif args.subparsers == 'compare':
        cmd_compare(args)
    else:
        pysemver.process(args)
